mapper.update:
update member
set withdrawal_date=#{withdrawalDate}
where provider_id = #{providerId}

update member
set member_password = #{memberPassword}
where member_email = #{memberEmail} and provider_id is null and withdrawal_date is null

update member
set member_email = #{memberEmail}, member_name = #{memberName}, member_nickname = #{memberNickname}, member_phone_number = #{memberPhoneNumber}
where member_no = #{memberNo}

mapper.select:
select member_no as memberNo, member_email as memberEmail, provider_id as providerId, member_password as memberPassword, member_name as memberName,member_nickname as memberNickname, member_phone_number as memberPhoneNumber, point, registration_date as registrationDate, withdrawal_date as withdrawalDate, authority
from member
where member_no = #{memberNo}

mapper.update:
update member
set withdrawal_date = current_timestamp()
where member_no = #{memberNo}
